demo.assessmentRecords ||= D.assessments.map(r=>({id:r.url,title:r.Assessment,date:dt(r),status:r.Status||'Scheduled',form:r['Assessment Form']||'',notes:r.Notes||'',weak:r['Main Weak Areas']||'',score:'',metric:'EPC %',probability:'',actualDate:''}));
