nav[3][1]=nav[3][1].map(x=>x[0]==='howto'?['howto','↗','How to use this app']:x);nav[2][1]=nav[2][1].map(x=>x[0]==='phases'?['phases','≋','Study roadmap']:x);
const isoDay=d=>d.toISOString().slice(0,10),shiftDay=(date,n)=>{const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return isoDay(d)};
const total=(rows,key)=>rows.reduce((n,x)=>n+(Number(x[key])||0),0);
function appSave(){try{localStorage.setItem('zahoor-atlas-prototype',JSON.stringify({demo,ui:{date:state.date,month:state.month,year:state.year}}));return true}catch{toast('Storage is full or unavailable. Export a backup before leaving this page.');return false}}
